import express from"express";import cors from"cors";import fs from"fs";import{createServer}from"http";import{Server}from"socket.io";import{initializeApp,cert}from"firebase-admin/app";import{getFirestore}from"firebase-admin/firestore";const app=express(),server=createServer(app),io=new Server(server,{cors:{origin:"*",methods:["GET","POST","PUT"]}});app.use(cors()),app.use(express.json());const keyPath=fs.existsSync("/etc/secrets/firebase-key.json")?"/etc/secrets/firebase-key.json":"./firebase-key.json",serviceAccount=JSON.parse(fs.readFileSync(keyPath,"utf8"));initializeApp({credential:cert(serviceAccount)});const db=getFirestore();console.log("Admin Backend: Connected to Firebase Cloud!"),app.get("/",(e,o)=>{o.send("GD & Associates Admin Backend is running live!")}),io.on("connection",e=>{e.on("customer_created_booking",e=>{io.emit("new_booking_alert",e)})}),app.get("/api/admin/bookings",async(e,o)=>{try{const e=(await db.collection("bookings").get()).docs.map(e=>({...e.data(),_id:e.id}));o.status(200).json(e)}catch(e){console.error(e),o.status(500).json({error:"Failed to fetch bookings"})}}),app.put("/api/bookings/:id",async(e,o)=>{try{const s=e.params.id,r=e.body,t=db.collection("bookings").doc(s);if(!(await t.get()).exists)return o.status(404).json({success:!1,error:"Booking not found"});await t.update(r);const i=await t.get();o.status(200).json({success:!0,data:{...i.data(),_id:i.id}})}catch(e){console.error("Update error:",e),o.status(500).json({success:!1,error:"Failed to update booking"})}});const PORT=process.env.PORT||5001;server.listen(PORT,"0.0.0.0",()=>console.log(`Admin Backend running on Port ${PORT}`));